import { useState } from 'react';
import PageHeader from '../../../components/shared/PageHeader';
import { useToast } from '../../../context/ToastContext';
import { useAuth } from '../../../context/AuthContext';
import { approvalsApi } from '../../../services/api';

export default function AddExpensePage() {
  const toast = useToast();
  const { user } = useAuth();
  const [form, setForm] = useState({
    userCert: user?.userCert || '',
    amount: '',
    fundId: '',
    description: '',
  });
  const [loading, setLoading] = useState(false);

  const onChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const onSubmit = async () => {
    if (!form.userCert || !form.fundId || !form.description || !form.amount) {
      toast('All fields are required', 'error');
      return;
    }
    setLoading(true);
    try {
      await approvalsApi.create({
        createdBy: form.userCert,
        ngoId: form.userCert,
        fundId: form.fundId,
        amount: form.amount,
        description: form.description,
        note: 'Expense approval request',
      });
      toast('Expense approval requested successfully', 'success');
      setForm((prev) => ({ ...prev, fundId: '', description: '', amount: '' }));
    } catch (err) {
      toast(err?.response?.data?.error || err.message || 'Failed to request approval', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <PageHeader title="Request Expense Approval" desc="Submit an expense for admin approval" />
      <div className="card">
        <div className="form-grid section-gap">
          <div className="form-group"><label>User Cert</label><input name="userCert" value={form.userCert} onChange={onChange} placeholder="ngo001" /></div>
          <div className="form-group"><label>Fund ID</label><input name="fundId" value={form.fundId} onChange={onChange} placeholder="fund001" /></div>
          <div className="form-group"><label>Description</label><input name="description" value={form.description} onChange={onChange} placeholder="Purchased medicine kits" /></div>
          <div className="form-group"><label>Amount</label><input name="amount" value={form.amount} onChange={onChange} type="number" placeholder="250" /></div>
          <div className="form-actions">
            <button className="btn btn-secondary" onClick={() => setForm((prev) => ({ ...prev, fundId: '', description: '', amount: '' }))}>Clear</button>
            <button className="btn btn-primary" onClick={onSubmit} disabled={loading}>{loading ? 'Submitting...' : 'Request Approval'}</button>
          </div>
        </div>
      </div>
    </div>
  );
}
